    // Check if any sound in a group is selected
    func isGroupSelected(_ displayableSound: DisplayableSound) -> Bool {
        for underlying in displayableSound.underlyingSounds {
            if selectedSounds.contains(underlying) {
                return true
            }
        }
        return false
    }

    // Toggle selection for a displayable sound (handles groups)
    func toggleDisplayableSoundSelection(_ displayableSound: DisplayableSound) {
        let isCurrentlySelected = isGroupSelected(displayableSound)

        for underlying in displayableSound.underlyingSounds {
            if isCurrentlySelected {
                selectedSounds.remove(underlying)
            } else {
                selectedSounds.insert(underlying)
            }
        }
    }

    // Select All or Deselect All sounds
    func toggleSelectAll() {
        withAnimation(.spring(response: 0.35, dampingFraction: 0.8)) {
            if selectedSounds.count == soundOptions.count {
                // Deselect all
                selectedSounds.removeAll()
            } else {
                // Select all (only non-premium for non-subscribers)
                if globalState.isSubscribed {
                    selectedSounds = soundOptions
                } else {
                    // Only select free sounds
                    selectedSounds = soundOptions.filter { sound in
                        !isPremiumSound(sound.displayName)
                    }
                }
            }
            activeFocusGroupId = nil
            activeSemanticModes.removeAll()
            saveSelectedSounds()
            saveActiveFocusSelection()
            appState.updateSelectedSounds(selectedSounds)
        }
    }

